// Dane z webhooka są w $json.body - spłaszczamy je, żeby dalej używać $json.pole
const src = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const required = ["fileUrl"];
const missing = required.filter((k) => src[k] === undefined || src[k] === null || String(src[k]).trim() === '');
if (missing.length) {
  throw new Error('Brak wymaganych pól: ' + missing.join(', '));
}
const clean = {};
for (const [k, v] of Object.entries(src)) {
  clean[k] = typeof v === 'string' ? v.trim().slice(0, 5000) : v;
}
if (clean.email !== undefined && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(clean.email))) {
  throw new Error('Niepoprawny adres e-mail');
}
return { json: { ...clean, _odebrano: new Date().toISOString() } };

const text = $json.responses?.[0]?.fullTextAnnotation?.text || '';
if (!text) throw new Error('OCR nie zwrócił tekstu');
return { json: { fileUrl: $('Walidacja danych').item.json.fileUrl, text } };

const SYSTEM = "Wyciągasz dane z tekstu dokumentu księgowego (faktura, paragon, umowa). Pola, których nie ma w tekście, ustaw na null.\n\nOdpowiedz WYŁĄCZNIE poprawnym obiektem JSON z polami: {\"typ\": \"faktura\" | \"paragon\" | \"umowa\" | \"inny\", \"numer\": tekst lub null, \"data\": YYYY-MM-DD lub null, \"kwotaBrutto\": liczba lub null, \"nipSprzedawcy\": tekst lub null, \"sprzedawca\": tekst lub null, \"pewnosc\": liczba 0-1}. Nie wymyślaj faktów, cen ani danych, których nie ma w treści.";
const user = `Tekst dokumentu:\n${$json.text}`;
return {
  json: {
    ...$json,
    _aiRequest: {
      model: ($('Konfiguracja').first().json.modelAI || "gpt-4o-mini"),
      max_tokens: 600,
      temperature: 0.3,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: String(user).slice(0, 12000) },
      ],
    },
  },
};

// Łączymy dane wejściowe (sprzed wywołania AI) z odpowiedzią modelu.
const ctx = { ...$('AI: prompt (ekstrakcja pól)').item.json };
delete ctx._aiRequest;
let out = {};
let aiError = '';
try {
  const raw = $json.choices?.[0]?.message?.content ?? '';
  out = JSON.parse(raw);
  if (!out || typeof out !== 'object' || Array.isArray(out)) throw new Error('to nie obiekt');
} catch (e) {
  aiError = 'Nie udało się odczytać odpowiedzi AI: ' + e.message;
  out = {};
}
const defaults = {"typ":"","numer":"","data":"","kwotaBrutto":"","nipSprzedawcy":"","sprzedawca":"","pewnosc":0};
for (const [k, v] of Object.entries(defaults)) if (out[k] === undefined || out[k] === null) out[k] = v;
for (const [k, v] of Object.entries(out)) if (typeof v === 'string') out[k] = v.slice(0, 4000);
out.pewnosc = Math.max(0, Math.min(1, Number(out.pewnosc)));
if (!Number.isFinite(out.pewnosc)) out.pewnosc = 0;
return { json: { ...ctx, ...out, _aiOk: !aiError, _aiError: aiError } };
